CREATE OR REPLACE FUNCTION public.wassell_geo_match_ids(p_client_id uuid)
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '25s'
AS $function$
  select coalesce(array_agg(record_id), '{}'::uuid[])
  from public.wassell_geo_match(p_client_id)
$function$;
CREATE OR REPLACE FUNCTION public.wassell_geo_region_contains(p_geom geometry, p_ref geometry, p_dir text, p_pt geometry)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  SELECT p_pt IS NOT NULL
     AND (p_geom IS NOT NULL OR p_dir IS NOT NULL)
     AND (p_geom IS NULL OR (p_pt && p_geom AND ST_Contains(p_geom, p_pt)))
     AND (p_dir  IS NULL OR public.wassell_geo_dir_match(p_ref, p_pt, p_dir))
$function$;
CREATE OR REPLACE FUNCTION public.wassell_import_geo_elements(p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count int;
BEGIN
  INSERT INTO public.geo_elements
    (external_id, element_type, category, type, geom_kind, name_ar, name_en, display_name,
     city, latitude, longitude, geom, centroid_geog, source_url, source_type,
     confidence_score, is_verified, is_approximate, review_status, is_searchable, notes, raw)
  SELECT
    r->>'id', r->>'category', r->>'category', r->>'type',
    coalesce(nullif(r->>'geometry_type',''), 'point'),
    nullif(r->>'name_ar',''), nullif(r->>'name_en',''),
    coalesce(nullif(r->>'name_en',''), nullif(r->>'name_ar',''), r->>'id'),
    nullif(r->>'city',''),
    nullif(r->>'latitude','')::double precision, nullif(r->>'longitude','')::double precision,
    CASE WHEN jsonb_typeof(r->'geometry_geojson') = 'object'
         THEN ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON(r->>'geometry_geojson'), 4326)) END,
    CASE WHEN nullif(r->>'latitude','') IS NOT NULL AND nullif(r->>'longitude','') IS NOT NULL
         THEN ST_SetSRID(ST_MakePoint((r->>'longitude')::double precision,(r->>'latitude')::double precision),4326)::geography END,
    nullif(r->>'source_url',''), nullif(r->>'source_type',''),
    nullif(r->>'confidence_score','')::numeric,
    coalesce((r->>'is_verified')::boolean, false), coalesce((r->>'is_approximate')::boolean, false),
    'approved', true, nullif(r->>'notes',''), r
  FROM jsonb_array_elements(p_rows) AS r
  WHERE coalesce(r->>'id','') <> ''
  ON CONFLICT (external_id) WHERE external_id IS NOT NULL DO UPDATE SET
    element_type=excluded.element_type, category=excluded.category, type=excluded.type,
    geom_kind=excluded.geom_kind, name_ar=excluded.name_ar, name_en=excluded.name_en,
    display_name=excluded.display_name, city=excluded.city,
    latitude=excluded.latitude, longitude=excluded.longitude,
    geom=excluded.geom, centroid_geog=excluded.centroid_geog,
    source_url=excluded.source_url, source_type=excluded.source_type,
    confidence_score=excluded.confidence_score, is_verified=excluded.is_verified,
    is_approximate=excluded.is_approximate, notes=excluded.notes, raw=excluded.raw, updated_at=now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('upserted', v_count);
END;$function$;
CREATE OR REPLACE FUNCTION public.wassell_is_admin(auth_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE((
    SELECT p.is_admin FROM profiles p
      JOIN users u ON u.profile_id = p.id
     WHERE u.auth_uid = auth_user_id AND u.is_active = true LIMIT 1
  ), false);
$function$;
CREATE OR REPLACE FUNCTION public.wassell_is_public_lookup_target(target_record_id uuid, target_model_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.records project_rec
    JOIN public.models all_projects_model
      ON all_projects_model.id = project_rec.model_id
      AND all_projects_model.name = 'all_projects'
    , jsonb_array_elements(all_projects_model.schema->'sections') sec
    , jsonb_array_elements(sec->'fields') f
    WHERE COALESCE((project_rec.data->>'is_public')::boolean, false) = true
      AND f->>'type' = 'lookup'
      AND f->>'lookup_model_id' IS NOT NULL
      AND (f->>'lookup_model_id')::uuid = target_model_id
      AND (
        project_rec.data->>(f->>'name') = target_record_id::text
        OR
        (
          jsonb_typeof(project_rec.data->(f->>'name')) = 'array'
          AND project_rec.data->(f->>'name') ? target_record_id::text
        )
      )
  );
$function$;
CREATE OR REPLACE FUNCTION public.wassell_link_geo_elements_geography(p_only_null boolean DEFAULT true, p_fallback_km numeric DEFAULT 25, p_sync_label boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contained int := 0;
  v_nearest   int := 0;
  v_unmatched int := 0;
  v_relabel   int := 0;
BEGIN
  WITH tgt AS (
    SELECT e.id, e.centroid_geog
    FROM public.geo_elements e
    WHERE e.centroid_geog IS NOT NULL
      AND (NOT p_only_null OR e.city_id IS NULL)
  ), hit AS (
    SELECT DISTINCT ON (t.id)
           t.id, b.city_id, b.region_id
    FROM tgt t
    JOIN public.district_boundaries b
      ON b.is_active
     AND ST_Intersects(b.geom, t.centroid_geog::geometry)
    ORDER BY t.id, b.spl_district_id
  )
  UPDATE public.geo_elements e
     SET city_id = h.city_id, region_id = h.region_id
    FROM hit h
   WHERE h.id = e.id;
  GET DIAGNOSTICS v_contained = ROW_COUNT;

  WITH tgt AS (
    SELECT e.id, e.centroid_geog
    FROM public.geo_elements e
    WHERE e.centroid_geog IS NOT NULL
      AND e.city_id IS NULL
  ), near AS (
    SELECT t.id, k.city_id, k.region_id
    FROM tgt t
    CROSS JOIN LATERAL (
      SELECT b.city_id, b.region_id, b.geom
      FROM public.district_boundaries b
      WHERE b.is_active
      ORDER BY b.geom <-> t.centroid_geog::geometry
      LIMIT 1
    ) k
    WHERE ST_DWithin(k.geom::geography, t.centroid_geog, p_fallback_km * 1000)
  )
  UPDATE public.geo_elements e
     SET city_id = n.city_id, region_id = n.region_id
    FROM near n
   WHERE n.id = e.id;
  GET DIAGNOSTICS v_nearest = ROW_COUNT;

  IF p_sync_label THEN
    WITH city AS (
      SELECT r.data->>'spl_city_id' AS spl, r.data->>'name_en' AS name_en
      FROM public.unified_records r
      JOIN public.models m ON m.id = r.model_id
      WHERE m.name = 'cities' AND coalesce(r.data->>'name_en', '') <> ''
    )
    UPDATE public.geo_elements e
       SET city = c.name_en
      FROM city c
     WHERE c.spl = e.city_id
       AND e.city IS DISTINCT FROM c.name_en;
    GET DIAGNOSTICS v_relabel = ROW_COUNT;
  END IF;

  SELECT count(*) INTO v_unmatched
    FROM public.geo_elements
   WHERE centroid_geog IS NOT NULL AND city_id IS NULL;

  RETURN jsonb_build_object(
    'linked_by_containment', v_contained,
    'linked_by_nearest',     v_nearest,
    'relabelled',            v_relabel,
    'still_unlinked',        v_unmatched,
    'fallback_km',           p_fallback_km
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_market_area_stats(p_items jsonb DEFAULT '[]'::jsonb, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_market_model_id uuid := '8f06bc39-4bee-42e9-9fab-77023fb89ede';
  v_units_model_id  uuid := '7ca3014d-f658-418e-9c53-2d279c97f009';
  v_our_model_id    uuid := '6609286a-f95a-45db-94e6-48cfa915ccbd';
  v_all_proj_model_id uuid := '220c49b9-de57-492d-9eca-c0d9f54fd40f';
  v_clients_model_id  uuid := '2e86f197-385f-4853-908f-b4cb7237f7d8';
  v_tmp uuid;
  v_has_geo boolean := jsonb_typeof(p_items) = 'array' AND jsonb_array_length(p_items) > 0;
  v_active_only boolean := coalesce((p_filters->>'active_only')::boolean, true);
  v_ptype text := nullif(p_filters->>'property_type','');
  v_bbucket text := nullif(p_filters->>'bedrooms_bucket','');
  v_city text := nullif(p_filters->>'city_id','');
  v_dids text[] := CASE WHEN p_filters ? 'district_ids'
                        THEN ARRAY(SELECT jsonb_array_elements_text(p_filters->'district_ids'))
                        END;
  v_geo_status jsonb;
  v_raw int := 0;
  v_ded int := 0;
  v_dupe numeric := 0;
  v_out jsonb;
  v_price jsonb; v_ppm2 jsonb; v_median_area numeric;
  v_by_type jsonb; v_by_bed jsonb; v_districts jsonb;
  v_our jsonb; v_demand jsonb;
BEGIN
  DROP TABLE IF EXISTS _area_ids;
  DROP TABLE IF EXISTS _area_norm;
  DROP TABLE IF EXISTS _area_dedup;

  CREATE TEMP TABLE _area_ids (record_id uuid PRIMARY KEY) ON COMMIT DROP;

  IF v_has_geo THEN
    v_tmp := gen_random_uuid();
    PERFORM public.wassell_compile_geo_items(v_tmp, p_items);

    SELECT jsonb_agg(jsonb_build_object(
             'item_id', item_id, 'kind', kind, 'polarity', polarity,
             'validation_status', validation_status))
      INTO v_geo_status
      FROM public.client_pref_geometry WHERE client_id = v_tmp;

    INSERT INTO _area_ids (record_id)
    SELECT m.record_id FROM public.wassell_geo_match(v_tmp) m
    ON CONFLICT DO NOTHING;

    DELETE FROM public.client_pref_geometry WHERE client_id = v_tmp;
  ELSE
    INSERT INTO _area_ids (record_id)
    SELECT lp.record_id FROM public.listing_points lp
    WHERE lp.geom IS NOT NULL
      AND (NOT v_active_only OR lp.is_active)
      AND (v_dids IS NULL OR lp.district_id::text = ANY(v_dids))
    ON CONFLICT DO NOTHING;

    INSERT INTO _area_ids (record_id)
    SELECT pp.record_id FROM public.project_points pp
    WHERE pp.geom IS NOT NULL
      AND (v_dids IS NULL OR pp.district_id::text = ANY(v_dids))
    ON CONFLICT DO NOTHING;
  END IF;

  CREATE TEMP TABLE _area_norm ON COMMIT DROP AS
  SELECT
    r.id,
    (r.data->'location'->>'city')     AS city_id,
    (r.data->'location'->>'district') AS district_id,
    public.wassell_canon_property_type(r.data->>'property_type') AS canon_type,
    nullif(r.data->>'price','')::numeric        AS price,
    nullif(r.data->>'area','')::numeric         AS area,
    nullif(r.data->>'price_per_m2','')::numeric AS ppm2,
    nullif(r.data->>'bedrooms','')::numeric     AS bedrooms,
    public.wassell_bedrooms_bucket(nullif(r.data->>'bedrooms','')::numeric) AS bbucket,
    md5(coalesce(r.data->'location'->>'district','') || '|' ||
        public.wassell_canon_property_type(r.data->>'property_type') || '|' ||
        coalesce(round(nullif(r.data->>'price','')::numeric)::text,'') || '|' ||
        coalesce(round(nullif(r.data->>'area','')::numeric)::text,'') || '|' ||
        coalesce(r.data->>'bedrooms','') || '|' ||
        coalesce(round(nullif(r.data->>'latitude','')::numeric, 4)::text,'') || '|' ||
        coalesce(round(nullif(r.data->>'longitude','')::numeric, 4)::text,'')
    ) AS fingerprint
  FROM public.records r
  JOIN _area_ids a ON a.record_id = r.id
  WHERE r.model_id = v_market_model_id
    AND coalesce(r.data->>'listing_type','sale') = 'sale'
    AND (NOT v_active_only OR coalesce(r.data->>'is_active','true') = 'true')
    AND nullif(r.data->>'price','')::numeric > 0
    AND nullif(r.data->>'area','')::numeric > 0
    AND nullif(r.data->>'price_per_m2','')::numeric > 0;

  IF v_ptype IS NOT NULL THEN
    DELETE FROM _area_norm WHERE canon_type <> v_ptype;
  END IF;
  IF v_bbucket IS NOT NULL AND v_bbucket <> 'all' THEN
    DELETE FROM _area_norm WHERE bbucket <> v_bbucket;
  END IF;
  IF v_city IS NOT NULL THEN
    DELETE FROM _area_norm WHERE city_id IS DISTINCT FROM v_city;
  END IF;

  CREATE TEMP TABLE _area_dedup ON COMMIT DROP AS
  SELECT DISTINCT ON (fingerprint) * FROM _area_norm ORDER BY fingerprint;

  SELECT count(*) INTO v_raw FROM _area_norm;
  SELECT count(*) INTO v_ded FROM _area_dedup;
  v_dupe := CASE WHEN v_raw = 0 THEN 0
                 ELSE round(1 - (v_ded::numeric / v_raw), 4) END;

  SELECT jsonb_build_object(
           'median', percentile_cont(0.5) WITHIN GROUP (ORDER BY price),
           'p10',    percentile_cont(0.1) WITHIN GROUP (ORDER BY price),
           'p25',    percentile_cont(0.25) WITHIN GROUP (ORDER BY price),
           'p75',    percentile_cont(0.75) WITHIN GROUP (ORDER BY price),
           'p90',    percentile_cont(0.9) WITHIN GROUP (ORDER BY price)),
         jsonb_build_object(
           'median', percentile_cont(0.5) WITHIN GROUP (ORDER BY ppm2),
           'p10',    percentile_cont(0.1) WITHIN GROUP (ORDER BY ppm2),
           'p25',    percentile_cont(0.25) WITHIN GROUP (ORDER BY ppm2),
           'p75',    percentile_cont(0.75) WITHIN GROUP (ORDER BY ppm2),
           'p90',    percentile_cont(0.9) WITHIN GROUP (ORDER BY ppm2),
           'min',    min(ppm2), 'max', max(ppm2)),
         percentile_cont(0.5) WITHIN GROUP (ORDER BY area)
    INTO v_price, v_ppm2, v_median_area
    FROM _area_dedup;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'count')::int DESC), '[]'::jsonb) INTO v_by_type
  FROM (
    SELECT jsonb_build_object(
             'property_type', canon_type,
             'count', count(*)::int,
             'median_price', percentile_cont(0.5) WITHIN GROUP (ORDER BY price),
             'median_price_per_sqm', percentile_cont(0.5) WITHIN GROUP (ORDER BY ppm2),
             'p25_price_per_sqm', percentile_cont(0.25) WITHIN GROUP (ORDER BY ppm2),
             'p75_price_per_sqm', percentile_cont(0.75) WITHIN GROUP (ORDER BY ppm2),
             'median_area', percentile_cont(0.5) WITHIN GROUP (ORDER BY area)) AS x
    FROM _area_dedup GROUP BY canon_type
  ) s;

  SELECT coalesce(jsonb_agg(x ORDER BY x->>'bedrooms_bucket'), '[]'::jsonb) INTO v_by_bed
  FROM (
    SELECT jsonb_build_object(
             'bedrooms_bucket', bbucket,
             'count', count(*)::int,
             'median_price', percentile_cont(0.5) WITHIN GROUP (ORDER BY price),
             'median_price_per_sqm', percentile_cont(0.5) WITHIN GROUP (ORDER BY ppm2)) AS x
    FROM _area_dedup WHERE bbucket <> 'all' GROUP BY bbucket
  ) s;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'count')::int DESC), '[]'::jsonb) INTO v_districts
  FROM (
    SELECT jsonb_build_object(
             'district_id', d.district_id,
             'district_name', max(coalesce(dr.name_ar, dr.display_name)),
             'district_name_en', max(dr.name_en),
             'city_name', max(dr.city_name_ar),
             'count', count(*)::int,
             'median_price_per_sqm', percentile_cont(0.5) WITHIN GROUP (ORDER BY d.ppm2)) AS x
    FROM _area_dedup d
    LEFT JOIN public.districts dr ON dr.id = d.district_id::uuid
    WHERE d.district_id IS NOT NULL
    GROUP BY d.district_id
  ) s;

  WITH ours AS (
    SELECT DISTINCT (data->>'project') AS project_id
    FROM public.records WHERE model_id = v_our_model_id
  ),
  proj AS (
    SELECT pr.id
    FROM public.records pr
    JOIN _area_ids a ON a.record_id = pr.id
    JOIN ours o ON o.project_id = pr.id::text
    WHERE pr.model_id = v_all_proj_model_id
  ),
  un AS (
    SELECT u.id, u.data
    FROM public.records u
    JOIN proj p ON u.data->>'project_id' = p.id::text
    WHERE u.model_id = v_units_model_id
  )
  SELECT jsonb_build_object(
           'project_count', (SELECT count(*) FROM proj),
           'unit_count', (SELECT count(*) FROM un),
           'available_units', (SELECT count(*) FROM un
             WHERE coalesce(un.data->>'unit_status','') ILIKE '%متاح%'
                OR coalesce(un.data->>'unit_status','') ILIKE '%available%'),
           'median_price_per_sqm', (
             SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY ppm2) FROM (
               SELECT nullif(un.data->>'total_price','')::numeric
                      / nullif(un.data->>'unit_area','')::numeric AS ppm2
               FROM un
               WHERE nullif(un.data->>'total_price','')::numeric > 0
                 AND nullif(un.data->>'unit_area','')::numeric > 0) q),
           'median_price', (
             SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY p) FROM (
               SELECT nullif(un.data->>'total_price','')::numeric AS p FROM un
               WHERE nullif(un.data->>'total_price','')::numeric > 0) q))
    INTO v_our;

  SELECT jsonb_build_object(
           'active_clients', count(DISTINCT c.id),
           'basis', 'district_preferences_only')
    INTO v_demand
    FROM public.records c
    WHERE c.model_id = v_clients_model_id
      AND EXISTS (
        SELECT 1
        FROM jsonb_array_elements(
               CASE WHEN jsonb_typeof(c.data->'location_items') = 'array'
                    THEN c.data->'location_items' ELSE '[]'::jsonb END) li
        WHERE li->>'kind' = 'district'
          AND coalesce(li->>'polarity','include') = 'include'
          AND li->>'district_id' IN (
            SELECT jsonb_array_elements(v_districts)->>'district_id'));

  v_out := jsonb_build_object(
    'raw_count', v_raw,
    'deduped_count', v_ded,
    'duplicate_ratio', v_dupe,
    'confidence_grade', public.wassell_benchmark_confidence(v_ded, v_dupe, 'asking', false),
    'confidence_reason', v_ded::text || ' deduped of ' || v_raw::text || ' asking ads in this area',
    'active_only', v_active_only,
    'has_geometry', v_has_geo,
    'geo_items', coalesce(v_geo_status, '[]'::jsonb),
    'price', coalesce(v_price, '{}'::jsonb),
    'price_per_sqm', coalesce(v_ppm2, '{}'::jsonb),
    'median_area', v_median_area,
    'by_type', v_by_type,
    'by_bedrooms', v_by_bed,
    'districts', v_districts,
    'our_inventory', coalesce(v_our, '{}'::jsonb),
    'demand', coalesce(v_demand, '{}'::jsonb),
    'snapshot_date', CURRENT_DATE
  );

  DROP TABLE IF EXISTS _area_ids;
  DROP TABLE IF EXISTS _area_norm;
  DROP TABLE IF EXISTS _area_dedup;

  RETURN v_out;
END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_market_candidate_count(p_model_id uuid, p_district_ids text[], p_budget_min numeric DEFAULT NULL::numeric, p_budget_max numeric DEFAULT NULL::numeric, p_bedrooms numeric DEFAULT NULL::numeric, p_type_terms text[] DEFAULT NULL::text[], p_record_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)
  from public.records r
  where r.model_id = p_model_id
    and (
      (p_record_ids is not null and r.id = any(p_record_ids))
      or (p_record_ids is null and p_district_ids is not null
          and (r.data -> 'location' ->> 'district') = any(p_district_ids))
    )
    and (
      p_budget_max is null
      or (r.data ->> 'price') is null
      or (r.data ->> 'price') !~ '^[0-9]+(\.[0-9]+)?$'
      or (
        (r.data ->> 'price')::numeric <= p_budget_max
        and (p_budget_min is null or (r.data ->> 'price')::numeric >= p_budget_min)
      )
    )
    and (
      p_bedrooms is null
      or (r.data ->> 'bedrooms') is null
      or (r.data ->> 'bedrooms') !~ '^[0-9]+(\.[0-9]+)?$'
      or (r.data ->> 'bedrooms')::numeric = p_bedrooms
    )
    and (
      p_type_terms is null
      or (
        coalesce(r.data ->> 'property_type', '') = ''
        and coalesce(r.data ->> 'listing_type', '') = ''
        and coalesce(r.data ->> 'category', '') = ''
      )
      or exists (
        select 1 from unnest(p_type_terms) t
        where (r.data ->> 'property_type') ilike '%' || t || '%'
           or (r.data ->> 'listing_type') ilike '%' || t || '%'
           or (r.data ->> 'category') ilike '%' || t || '%'
      )
    )
    and public.wassell_can_view_record(auth.uid(), r.*);
$function$;
CREATE OR REPLACE FUNCTION public.wassell_market_candidates(p_model_id uuid, p_district_ids text[], p_budget_min numeric DEFAULT NULL::numeric, p_budget_max numeric DEFAULT NULL::numeric, p_bedrooms numeric DEFAULT NULL::numeric, p_type_terms text[] DEFAULT NULL::text[], p_limit integer DEFAULT 4001, p_record_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(id uuid, data jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r.id, r.data
  from public.records r
  where r.model_id = p_model_id
    and (
      (p_record_ids is not null and r.id = any(p_record_ids))
      or (p_record_ids is null and p_district_ids is not null
          and (r.data -> 'location' ->> 'district') = any(p_district_ids))
    )
    and (
      p_budget_max is null
      or (r.data ->> 'price') is null
      or (r.data ->> 'price') !~ '^[0-9]+(\.[0-9]+)?$'
      or (
        (r.data ->> 'price')::numeric <= p_budget_max
        and (p_budget_min is null or (r.data ->> 'price')::numeric >= p_budget_min)
      )
    )
    and (
      p_bedrooms is null
      or (r.data ->> 'bedrooms') is null
      or (r.data ->> 'bedrooms') !~ '^[0-9]+(\.[0-9]+)?$'
      or (r.data ->> 'bedrooms')::numeric = p_bedrooms
    )
    and (
      p_type_terms is null
      or (
        coalesce(r.data ->> 'property_type', '') = ''
        and coalesce(r.data ->> 'listing_type', '') = ''
        and coalesce(r.data ->> 'category', '') = ''
      )
      or exists (
        select 1 from unnest(p_type_terms) t
        where (r.data ->> 'property_type') ilike '%' || t || '%'
           or (r.data ->> 'listing_type') ilike '%' || t || '%'
           or (r.data ->> 'category') ilike '%' || t || '%'
      )
    )
    and public.wassell_can_view_record(auth.uid(), r.*)
  order by r.id
  limit p_limit;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_market_candidates_json(p_model_id uuid, p_district_ids text[], p_budget_min numeric DEFAULT NULL::numeric, p_budget_max numeric DEFAULT NULL::numeric, p_bedrooms numeric DEFAULT NULL::numeric, p_type_terms text[] DEFAULT NULL::text[], p_limit integer DEFAULT 4000, p_record_ids uuid[] DEFAULT NULL::uuid[], p_fields text[] DEFAULT NULL::text[], p_max_age numeric DEFAULT NULL::numeric, p_area_min numeric DEFAULT NULL::numeric, p_area_max numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '25s'
AS $function$
DECLARE
  v_klass text := public.wassell_view_scope_class(auth.uid(), p_model_id);
  v_out jsonb;
BEGIN
  IF v_klass = 'none' THEN
    RETURN jsonb_build_object('total', 0, 'rows', '[]'::jsonb);
  END IF;

  IF p_record_ids IS NOT NULL AND v_klass = 'all' THEN
    WITH filtered AS MATERIALIZED (
      SELECT lp.record_id AS id
      FROM public.listing_points lp
      JOIN (SELECT unnest(p_record_ids) AS id) ids ON ids.id = lp.record_id
      WHERE (
          p_budget_max IS NULL OR lp.price IS NULL
          OR (lp.price <= p_budget_max AND (p_budget_min IS NULL OR lp.price >= p_budget_min))
        )
        AND (p_bedrooms IS NULL OR lp.bedrooms IS NULL OR lp.bedrooms >= p_bedrooms)
        AND (
          lp.area IS NULL
          OR ((p_area_min IS NULL OR lp.area >= p_area_min)
              AND (p_area_max IS NULL OR lp.area <= p_area_max))
        )
        AND (
          p_type_terms IS NULL
          OR coalesce(lp.type_text, '') = ''
          OR EXISTS (SELECT 1 FROM unnest(p_type_terms) t WHERE lp.type_text ILIKE '%' || t || '%')
        )
        AND (p_max_age IS NULL OR lp.unit_age IS NULL OR lp.unit_age <= p_max_age)
    ),
    tot AS (SELECT count(*) AS n FROM filtered),
    sel AS (SELECT id FROM filtered ORDER BY id LIMIT p_limit)
    SELECT jsonb_build_object(
      'total', (SELECT n FROM tot),
      'rows', CASE
        WHEN (SELECT n FROM tot) > p_limit THEN '[]'::jsonb
        ELSE coalesce(
          (SELECT jsonb_agg(jsonb_build_object(
                    'id', r.id,
                    'data', CASE
                      WHEN p_fields IS NULL THEN r.data
                      ELSE coalesce(
                        (SELECT jsonb_object_agg(key, value)
                           FROM jsonb_each(r.data) WHERE key = ANY(p_fields)),
                        '{}'::jsonb)
                    END
                  ) ORDER BY r.id)
             FROM public.records r
             JOIN sel s ON s.id = r.id),
          '[]'::jsonb)
      END)
    INTO v_out;
    RETURN v_out;
  END IF;

  WITH filtered AS MATERIALIZED (
    SELECT r.id
    FROM public.records r
    WHERE r.model_id = p_model_id
      AND (
        (p_record_ids IS NOT NULL AND r.id IN (SELECT unnest(p_record_ids)))
        OR (p_record_ids IS NULL AND p_district_ids IS NOT NULL
            AND (r.data -> 'location' ->> 'district') = ANY(p_district_ids))
      )
      AND (
        p_budget_max IS NULL
        OR (r.data ->> 'price') IS NULL
        OR (r.data ->> 'price') !~ '^[0-9]+(\.[0-9]+)?$'
        OR (
          (r.data ->> 'price')::numeric <= p_budget_max
          AND (p_budget_min IS NULL OR (r.data ->> 'price')::numeric >= p_budget_min)
        )
      )
      AND (
        p_bedrooms IS NULL
        OR (r.data ->> 'bedrooms') IS NULL
        OR (r.data ->> 'bedrooms') !~ '^[0-9]+(\.[0-9]+)?$'
        OR (r.data ->> 'bedrooms')::numeric >= p_bedrooms
      )
      AND (
        (p_area_min IS NULL AND p_area_max IS NULL)
        OR public.try_numeric(r.data ->> 'area') IS NULL
        OR (
          (p_area_min IS NULL OR public.try_numeric(r.data ->> 'area') >= p_area_min)
          AND (p_area_max IS NULL OR public.try_numeric(r.data ->> 'area') <= p_area_max)
        )
      )
      AND (
        p_type_terms IS NULL
        OR (
          coalesce(r.data ->> 'property_type', '') = ''
          AND coalesce(r.data ->> 'listing_type', '') = ''
          AND coalesce(r.data ->> 'category', '') = ''
        )
        OR EXISTS (
          SELECT 1 FROM unnest(p_type_terms) t
          WHERE (r.data ->> 'property_type') ILIKE '%' || t || '%'
             OR (r.data ->> 'listing_type') ILIKE '%' || t || '%'
             OR (r.data ->> 'category') ILIKE '%' || t || '%'
        )
      )
      AND (
        p_max_age IS NULL
        OR public.wassell_parse_unit_age(r.data ->> 'age') IS NULL
        OR public.wassell_parse_unit_age(r.data ->> 'age') <= p_max_age
      )
      AND (CASE WHEN v_klass = 'all' THEN true
                ELSE public.wassell_can_view_record(auth.uid(), r.*) END)
  ),
  tot AS (SELECT count(*) AS n FROM filtered),
  sel AS (SELECT id FROM filtered ORDER BY id LIMIT p_limit)
  SELECT jsonb_build_object(
    'total', (SELECT n FROM tot),
    'rows', CASE
      WHEN (SELECT n FROM tot) > p_limit THEN '[]'::jsonb
      ELSE coalesce(
        (SELECT jsonb_agg(jsonb_build_object(
                  'id', r.id,
                  'data', CASE
                    WHEN p_fields IS NULL THEN r.data
                    ELSE coalesce(
                      (SELECT jsonb_object_agg(key, value)
                         FROM jsonb_each(r.data) WHERE key = ANY(p_fields)),
                      '{}'::jsonb)
                  END
                ) ORDER BY r.id)
           FROM public.records r
           JOIN sel s ON s.id = r.id),
        '[]'::jsonb)
    END)
  INTO v_out;
  RETURN v_out;
END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_market_geo_coverage()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'in_scope',            count(*),
    'with_coordinates',    count(*) FILTER (WHERE lp.geom IS NOT NULL),
    'without_coordinates', count(*) FILTER (WHERE lp.geom IS NULL),
    'pct_without_coordinates',
      round(100.0 * count(*) FILTER (WHERE lp.geom IS NULL) / nullif(count(*), 0), 1))
  FROM public.records r
  LEFT JOIN public.listing_points lp ON lp.record_id = r.id
  WHERE r.model_id = '8f06bc39-4bee-42e9-9fab-77023fb89ede'
    AND coalesce(r.data->>'listing_type','sale') = 'sale'
    AND nullif(r.data->>'price','')::numeric > 0
    AND nullif(r.data->>'area','')::numeric > 0
    AND nullif(r.data->>'price_per_m2','')::numeric > 0;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_market_map_districts(p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_units_model_id uuid := '7ca3014d-f658-418e-9c53-2d279c97f009';
  v_clients_model_id uuid := '2e86f197-385f-4853-908f-b4cb7237f7d8';
  v_ptype   text := coalesce(nullif(p_filters->>'property_type',''), 'شقة');
  v_bbucket text := coalesce(nullif(p_filters->>'bedrooms_bucket',''), 'all');
  v_city    text := nullif(p_filters->>'city_id','');
  v_out jsonb;
BEGIN
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'district_id', b.district_id,
           'district_name', b.district_name,
           'district_name_en', b.district_name_en,
           'city_id', b.city_id,
           'city_name', b.city_name,
           'listing_count', b.deduped_count,
           'duplicate_ratio', b.duplicate_ratio,
           'confidence_grade', b.confidence_grade,
           'median_price', b.median_price,
           'median_price_per_sqm', b.median_price_per_sqm,
           'p25_price_per_sqm', b.p25_price_per_sqm,
           'p75_price_per_sqm', b.p75_price_per_sqm,
           'median_area', b.median_area,
           'our_units', coalesce(o.unit_count, 0),
           'demand_clients', coalesce(dm.client_count, 0),
           'centroid', CASE WHEN dr.centroid_lat IS NULL OR dr.centroid_lng IS NULL THEN NULL
                       ELSE jsonb_build_array(dr.centroid_lng, dr.centroid_lat) END,
           'outline', CASE WHEN db.geom IS NULL THEN NULL
                      ELSE ST_AsGeoJSON(ST_SimplifyPreserveTopology(db.geom, 0.0005), 5)::jsonb END
         )), '[]'::jsonb)
    INTO v_out
    FROM public.market_benchmarks b
    LEFT JOIN public.districts dr ON dr.id = b.district_id::uuid
    LEFT JOIN public.district_boundaries db
      ON db.district_record_id = b.district_id::uuid AND db.is_active
    LEFT JOIN LATERAL (
      SELECT count(*)::int AS unit_count
      FROM public.records u
      JOIN public.project_points pp ON pp.record_id::text = u.data->>'project_id'
      WHERE u.model_id = v_units_model_id
        AND pp.district_id = b.district_id::uuid
    ) o ON true
    LEFT JOIN LATERAL (
      SELECT count(*)::int AS client_count
      FROM public.records c
      WHERE c.model_id = v_clients_model_id
        AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(
                 CASE WHEN jsonb_typeof(c.data->'location_items') = 'array'
                      THEN c.data->'location_items' ELSE '[]'::jsonb END) li
          WHERE li->>'kind' = 'district'
            AND coalesce(li->>'polarity','include') = 'include'
            AND li->>'district_id' = b.district_id)
    ) dm ON true
   WHERE b.snapshot_date = (SELECT max(snapshot_date) FROM public.market_benchmarks)
     AND b.source_type = 'asking'
     AND b.property_type = v_ptype
     AND b.bedrooms_bucket = v_bbucket
     AND (v_city IS NULL OR b.city_id = v_city)
     AND b.district_id IS NOT NULL;

  RETURN v_out;
END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_mkt_can(p_capability text, p_auth_uid uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE public.wassell_mkt_role(p_auth_uid)
    WHEN 'administrator'     THEN true
    WHEN 'marketing_manager' THEN true
    WHEN 'content_manager'   THEN p_capability IN (
        'read','write_content','write_campaign','comment','assign','schedule','approve_content',
        'read_strategy','read_plan','manage_goals','manage_initiatives','manage_programs',
        'manage_campaigns','manage_capacity','review_performance')
    WHEN 'writer'            THEN p_capability IN ('read','write_content','comment','read_strategy','read_plan')
    WHEN 'designer'          THEN p_capability IN ('read','write_content','comment','read_strategy','read_plan')
    WHEN 'video_editor'      THEN p_capability IN ('read','write_content','comment','read_strategy','read_plan')
    WHEN 'publisher'         THEN p_capability IN ('read','comment','schedule','publish','read_strategy','read_plan')
    WHEN 'reviewer'          THEN p_capability IN ('read','comment','approve_content','read_strategy','read_plan','review_performance')
    WHEN 'sales'             THEN p_capability IN ('read','comment','read_strategy','read_plan')
    WHEN 'viewer'            THEN p_capability IN ('read','read_strategy','read_plan')
    ELSE false
  END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_mkt_role(p_auth_uid uuid DEFAULT auth.uid())
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN p_auth_uid IS NULL THEN 'none'
    WHEN public.wassell_is_admin(p_auth_uid) THEN 'administrator'
    ELSE COALESCE((SELECT g.mkt_role FROM public.mkt_role_grants g
                    WHERE g.user_id = public.wassell_app_user_id(p_auth_uid)), 'viewer')
  END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_model_records_json(p_model_id uuid, p_fields text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '25s'
AS $function$
  with access as materialized (
    select public.wassell_view_scope_class(auth.uid(), p_model_id) as klass
  ),
  rows_src as materialized (
    select u.id, u.data
    from public.unified_records u
    cross join access a
    where a.klass <> 'none'
      and u.model_id = p_model_id
      and (case when a.klass = 'all' then true
                else public.wassell_can_view_jsonb(auth.uid(), p_model_id, u.id, u.created_by_user_id, u.data) end)
  )
  select coalesce(
    (select jsonb_agg(jsonb_build_object(
              'id', r.id,
              'data', case
                when p_fields is null then r.data
                else coalesce(
                  (select jsonb_object_agg(key, value)
                     from jsonb_each(r.data) where key = any(p_fields)),
                  '{}'::jsonb)
              end
            ) order by r.id)
       from rows_src r),
    '[]'::jsonb
  );
$function$;
CREATE OR REPLACE FUNCTION public.wassell_mos_can(p_capability text, p_auth_uid uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE public.wassell_mos_role(p_auth_uid)
    WHEN 'administrator'     THEN true
    WHEN 'marketing_manager' THEN true
    WHEN 'ceo' THEN p_capability IN ('read','comment','approve_budget','review_performance')
    WHEN 'ops_supervisor' THEN p_capability IN ('read','comment','assign','schedule','publish','approve_process','manage_assets','enter_metrics','review_performance')
    WHEN 'writer' THEN p_capability IN ('read','comment','write_content','schedule','publish')
    WHEN 'montage' THEN p_capability IN ('read','comment','write_content','manage_assets')
    WHEN 'viewer' THEN p_capability IN ('read')
    ELSE false
  END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_mos_role(p_auth_uid uuid DEFAULT auth.uid())
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN p_auth_uid IS NULL THEN 'none'
    WHEN public.wassell_is_admin(p_auth_uid) THEN 'administrator'
    ELSE COALESCE((SELECT g.mos_role FROM public.mos_role_grants g
        WHERE g.user_id = public.wassell_app_user_id(p_auth_uid)), 'viewer')
  END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_object_is_public_marketing(p_bucket text, p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.files f
    WHERE f.storage_bucket = p_bucket
      AND f.storage_path = p_name
      AND public.wassell_file_is_public_marketing(f.id)
  );
$function$;
CREATE OR REPLACE FUNCTION public.wassell_parse_unit_age(p_age text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  SELECT CASE
    WHEN p_age IS NULL OR btrim(p_age) = '' THEN NULL
    WHEN p_age LIKE '%جديد%' THEN 0
    WHEN p_age LIKE '%سنتين%' OR p_age LIKE '%سنتان%' THEN 2
    WHEN translate(p_age, '٠١٢٣٤٥٦٧٨٩', '0123456789') ~ '[0-9]' THEN
      CASE WHEN p_age LIKE '%أكثر%'
        THEN public.try_numeric(regexp_replace(translate(p_age, '٠١٢٣٤٥٦٧٨٩', '0123456789'), '[^0-9]', '', 'g')) + 1
        ELSE public.try_numeric(regexp_replace(translate(p_age, '٠١٢٣٤٥٦٧٨٩', '0123456789'), '[^0-9]', '', 'g'))
      END
    WHEN p_age LIKE '%سنة%' THEN 1
    ELSE NULL
  END
$function$;
CREATE OR REPLACE FUNCTION public.wassell_preview_geo_items(p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tmp uuid := gen_random_uuid();
  v_out jsonb;
BEGIN
  PERFORM public.wassell_compile_geo_items(v_tmp, p_items);

  SELECT jsonb_agg(jsonb_build_object(
    'item_id', g.item_id,
    'kind', g.kind,
    'polarity', g.polarity,
    'direction', g.direction,
    'validation_status', g.validation_status,
    'geojson', CASE
      WHEN g.geom IS NULL THEN NULL
      WHEN g.direction IS NOT NULL AND ln.line IS NOT NULL THEN
        ST_AsGeoJSON(ST_SimplifyPreserveTopology(coalesce(clip.side_geom, g.geom), 0.0002), 5)::jsonb
      ELSE ST_AsGeoJSON(ST_SimplifyPreserveTopology(g.geom, 0.0002), 5)::jsonb
    END,
    'ref_geojson', CASE WHEN g.ref_geom IS NOT NULL
      THEN ST_AsGeoJSON(ST_SimplifyPreserveTopology(g.ref_geom, 0.0002), 5)::jsonb END,
    'listing_count', CASE WHEN g.geom IS NULL THEN NULL ELSE (
      SELECT count(*) FROM public.listing_points lp
      WHERE lp.is_active AND lp.geom IS NOT NULL AND ST_Contains(g.geom, lp.geom)
        AND (g.direction IS NULL OR public.wassell_geo_dir_match(g.ref_geom, lp.geom, g.direction))
    ) END,
    'project_count', CASE WHEN g.geom IS NULL THEN NULL ELSE (
      SELECT count(*) FROM public.project_points pp
      WHERE pp.is_active AND pp.geom IS NOT NULL AND ST_Contains(g.geom, pp.geom)
        AND (g.direction IS NULL OR public.wassell_geo_dir_match(g.ref_geom, pp.geom, g.direction))
    ) END
  ) ORDER BY g.item_id)
  INTO v_out
  FROM public.client_pref_geometry g
  LEFT JOIN LATERAL (
    SELECT public._wassell_longest_line(g.ref_geom) AS line
  ) ln ON g.ref_geom IS NOT NULL
  LEFT JOIN LATERAL (
    SELECT (
      SELECT CASE WHEN c IS NULL OR ST_IsEmpty(c) THEN NULL ELSE c END FROM (
        SELECT ST_CollectionExtract(ST_Intersection(
          ST_MakeValid(g.geom),
          ST_MakeValid(ST_MakePolygon(ST_AddPoint(ST_MakeLine(
            ln.line,
            ST_Reverse(ST_Translate(ln.line,
              CASE g.direction WHEN 'east' THEN 1.0 WHEN 'west' THEN -1.0 ELSE 0 END,
              CASE g.direction WHEN 'north' THEN 1.0 WHEN 'south' THEN -1.0 ELSE 0 END))),
            ST_StartPoint(ln.line))))
        ), 3) AS c
      ) x
    ) AS side_geom
  ) clip ON g.direction IS NOT NULL AND ln.line IS NOT NULL
  WHERE g.client_id = v_tmp;

  DELETE FROM public.client_pref_geometry WHERE client_id = v_tmp;

  RETURN coalesce(v_out, '[]'::jsonb);
END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_project_in_our_projects(p_project_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.records r
    JOIN public.models m ON m.id = r.model_id AND m.name = 'our_projects'
    WHERE (CASE WHEN jsonb_typeof(r.data->'project') = 'array'
                THEN r.data->'project'->>0
                ELSE r.data->>'project' END) = p_project_id::text
  );
$function$;
CREATE OR REPLACE FUNCTION public.wassell_project_is_public(project_id_str text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.records p
    WHERE p.model_id IN (SELECT id FROM public.models WHERE name = 'all_projects')
      AND p.id::text = project_id_str
      AND COALESCE((p.data->>'is_public')::boolean, false) = true
  );
$function$;
CREATE OR REPLACE FUNCTION public.wassell_public_lookup_model_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT DISTINCT (f->>'lookup_model_id')::uuid
  FROM public.models m
  , jsonb_array_elements(m.schema->'sections') sec
  , jsonb_array_elements(sec->'fields') f
  WHERE m.name = 'all_projects'
    AND f->>'type' = 'lookup'
    AND f->>'lookup_model_id' IS NOT NULL;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_public_marketing_files(p_file_ids uuid[])
 RETURNS TABLE(file_id uuid, storage_bucket text, storage_path text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT f.id, f.storage_bucket, f.storage_path
  FROM public.files f
  WHERE f.id = ANY(p_file_ids)
    AND public.wassell_file_is_public_marketing(f.id);
$function$;
CREATE OR REPLACE FUNCTION public.wassell_rebuild_geo_aliases()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count int;
BEGIN
  INSERT INTO public.geo_element_aliases (element_id, external_id, alias, alias_norm, lang, source)
  SELECT e.id, e.external_id, v.alias, lower(btrim(v.alias)), v.lang, 'import'
  FROM public.geo_elements e
  CROSS JOIN LATERAL (VALUES (e.name_ar, 'ar'), (e.name_en, 'en')) AS v(alias, lang)
  WHERE e.external_id IS NOT NULL AND v.alias IS NOT NULL AND btrim(v.alias) <> ''
  ON CONFLICT (element_id, alias_norm, coalesce(lang,'')) DO NOTHING;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('aliases_added', v_count);
END;$function$;
CREATE OR REPLACE FUNCTION public.wassell_record_passes_scope(rec records, auth_user_id uuid, scope_kind text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  prof profiles%ROWTYPE;
  app_uid UUID;
  user_assignments jsonb;
  user_assignment jsonb;
  model_perm jsonb;
  rule jsonb;
  cond jsonb;
  field_kind TEXT;
  field_slug TEXT;
  rec_value jsonb;
  rec_value_text TEXT;
  source_kind TEXT;
  rhs_text TEXT;
  operator TEXT;
  pass boolean;
BEGIN
  IF auth_user_id IS NULL THEN RETURN false; END IF;
  SELECT u.id, u.role_assignments INTO app_uid, user_assignments
    FROM users u WHERE u.auth_uid = auth_user_id AND u.is_active = true LIMIT 1;
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT p.* INTO prof FROM profiles p
    JOIN users u ON u.profile_id = p.id WHERE u.id = app_uid LIMIT 1;
  IF NOT FOUND THEN RETURN false; END IF;
  IF prof.is_admin THEN RETURN true; END IF;

  SELECT mp INTO model_perm FROM jsonb_array_elements(prof.model_permissions) mp
    WHERE (mp->>'model_id')::uuid = rec.model_id LIMIT 1;
  IF model_perm IS NULL THEN RETURN false; END IF;

  rule := model_perm -> (scope_kind || '_scope');
  IF rule IS NULL THEN RETURN true; END IF;
  IF rule->>'mode' = 'all' THEN RETURN true; END IF;
  IF rule->>'mode' <> 'filtered' THEN RETURN true; END IF;
  IF jsonb_array_length(rule->'conditions') = 0 THEN RETURN true; END IF;

  FOR cond IN SELECT * FROM jsonb_array_elements(rule->'conditions')
  LOOP
    field_kind := cond->'field'->>'kind';
    operator := cond->>'operator';
    IF field_kind = 'created_by' THEN
      rec_value := to_jsonb(rec.created_by_user_id);
      rec_value_text := rec.created_by_user_id::text;
    ELSE
      field_slug := cond->'field'->>'field_slug';
      IF field_slug IS NULL THEN
        SELECT (f->>'name') INTO field_slug FROM models m,
          jsonb_array_elements(m.schema->'sections') s,
          jsonb_array_elements(s->'fields') f
         WHERE m.id = rec.model_id AND f->>'id' = cond->'field'->>'field_id' LIMIT 1;
      END IF;
      IF field_slug IS NULL THEN RETURN false; END IF;
      rec_value := rec.data -> field_slug;
      rec_value_text := rec.data ->> field_slug;
    END IF;

    IF operator = 'is_empty' THEN
      pass := rec_value IS NULL OR rec_value = 'null'::jsonb
              OR COALESCE(rec_value_text,'') = ''
              OR (jsonb_typeof(rec_value)='array' AND jsonb_array_length(rec_value)=0);
      IF NOT pass THEN RETURN false; END IF; CONTINUE;
    ELSIF operator = 'is_not_empty' THEN
      pass := rec_value IS NOT NULL AND rec_value <> 'null'::jsonb
              AND COALESCE(rec_value_text,'') <> ''
              AND (jsonb_typeof(rec_value)<>'array' OR jsonb_array_length(rec_value)>0);
      IF NOT pass THEN RETURN false; END IF; CONTINUE;
    END IF;

    source_kind := cond->'source'->>'kind';
    IF source_kind = 'literal' THEN
      rhs_text := cond->'source'->>'value';
    ELSIF source_kind = 'current_user' THEN
      rhs_text := app_uid::text;
    ELSIF source_kind = 'role_field' THEN
      SELECT a INTO user_assignment FROM jsonb_array_elements(COALESCE(user_assignments,'[]'::jsonb)) a
        WHERE a->>'role_id' = cond->'source'->>'role_id' LIMIT 1;
      IF user_assignment IS NULL THEN RETURN false; END IF;
      rhs_text := user_assignment->'field_values'->>(cond->'source'->>'field_slug');
      IF rhs_text IS NULL THEN RETURN false; END IF;
    ELSE RETURN false; END IF;

    IF operator = 'equals' THEN
      IF jsonb_typeof(rec_value)='array' THEN
        pass := EXISTS(SELECT 1 FROM jsonb_array_elements_text(rec_value) v WHERE v = rhs_text);
      ELSE pass := COALESCE(rec_value_text,'') = COALESCE(rhs_text,''); END IF;
    ELSIF operator = 'not_equals' THEN
      IF jsonb_typeof(rec_value)='array' THEN
        pass := NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(rec_value) v WHERE v = rhs_text);
      ELSE pass := rec_value_text IS DISTINCT FROM rhs_text; END IF;
    ELSIF operator = 'contains' THEN
      IF jsonb_typeof(rec_value)='array' THEN
        pass := EXISTS(SELECT 1 FROM jsonb_array_elements_text(rec_value) v
                        WHERE position(lower(rhs_text) IN lower(v)) > 0);
      ELSE pass := position(lower(COALESCE(rhs_text,'')) IN lower(COALESCE(rec_value_text,''))) > 0; END IF;
    ELSIF operator = 'greater_than' THEN
      BEGIN pass := rec_value_text::numeric > rhs_text::numeric; EXCEPTION WHEN OTHERS THEN pass := false; END;
    ELSIF operator = 'less_than' THEN
      BEGIN pass := rec_value_text::numeric < rhs_text::numeric; EXCEPTION WHEN OTHERS THEN pass := false; END;
    ELSE pass := false; END IF;
    IF NOT pass THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END $function$;
CREATE OR REPLACE FUNCTION public.wassell_refresh_demand_supply()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_clients_model uuid := '2e86f197-385f-4853-908f-b4cb7237f7d8';
  v_all_proj uuid := '220c49b9-de57-492d-9eca-c0d9f54fd40f';
  v_our_proj uuid := '6609286a-f95a-45db-94e6-48cfa915ccbd';
  v_today date := CURRENT_DATE;
  v_written int := 0;
BEGIN
  DELETE FROM public.market_demand_supply_benchmarks WHERE snapshot_date = v_today;

  CREATE TEMP TABLE _active ON COMMIT DROP AS
  SELECT id, data FROM public.records
  WHERE model_id = v_clients_model
    AND coalesce(data->>'client_status','') NOT IN ('غير مهتم','غير مؤهل','تم الإفراغ','تم البيع','مرفوض');

  CREATE TEMP TABLE _client_district ON COMMIT DROP AS
  SELECT DISTINCT client_id, district_id FROM (
    SELECT c.id AS client_id, jsonb_array_elements_text(c.data->'location'->'district') AS district_id
    FROM _active c WHERE jsonb_typeof(c.data->'location'->'district') = 'array'
    UNION
    SELECT c.id, (p.data->'location'->>'district')
    FROM _active c
    CROSS JOIN LATERAL jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(c.data->'preferred_projects')='array' THEN c.data->'preferred_projects' ELSE '[]'::jsonb END) pid
    JOIN public.records p ON p.id = pid::uuid AND p.model_id = v_all_proj
    WHERE p.data->'location'->>'district' IS NOT NULL
  ) s
  WHERE district_id IS NOT NULL AND district_id <> '';

  CREATE TEMP TABLE _client_type ON COMMIT DROP AS
  SELECT DISTINCT c.id AS client_id,
         public.wassell_canon_property_type(jsonb_array_elements_text(c.data->'preferred_unit_type')) AS canon_type
  FROM _active c WHERE jsonb_typeof(c.data->'preferred_unit_type') = 'array';

  CREATE TEMP TABLE _client_budget ON COMMIT DROP AS
  SELECT id AS client_id,
         public.wassell_budget_bucket(nullif(data->'budget'->>'max','')::numeric) AS budget_bucket
  FROM _active;

  CREATE TEMP TABLE _atoms ON COMMIT DROP AS
  SELECT cd.client_id, cd.district_id,
         coalesce(ct.canon_type, 'all') AS property_type,
         coalesce(cb.budget_bucket, 'all') AS budget_bucket
  FROM _client_district cd
  LEFT JOIN _client_type ct ON ct.client_id = cd.client_id
  LEFT JOIN _client_budget cb ON cb.client_id = cd.client_id;

  INSERT INTO public.market_demand_supply_benchmarks (
    snapshot_date, region_id, city_id, city_name, district_id, district_name, district_name_en,
    property_type, budget_bucket, active_client_count,
    matching_market_listing_count, matching_our_project_count, matching_all_project_count,
    undersupply_score, sales_priority_score, acquisition_priority_score, confidence_grade)
  SELECT
    v_today, max(dr.region_id), max(dr.city_id), max(dr.city_name_ar), a.district_id,
    max(coalesce(dr.name_ar, dr.display_name)), max(dr.name_en),
    a.property_type, a.budget_bucket,
    count(DISTINCT a.client_id) AS active_client_count,
    coalesce(mk.listing_count, 0),
    coalesce(op.our_count, 0),
    coalesce(ap.all_count, 0),
    round(count(DISTINCT a.client_id)::numeric / (coalesce(op.our_count,0) + 1), 2),
    (CASE WHEN coalesce(op.our_count,0) > 0 THEN count(DISTINCT a.client_id) ELSE 0 END)::numeric,
    (CASE WHEN coalesce(op.our_count,0) = 0 AND coalesce(mk.listing_count,0) >= 10
          THEN count(DISTINCT a.client_id) ELSE round(count(DISTINCT a.client_id) * 0.4, 1) END)::numeric,
    CASE WHEN count(DISTINCT a.client_id) >= 8 THEN 'high'
         WHEN count(DISTINCT a.client_id) >= 3 THEN 'medium' ELSE 'low' END
  FROM _atoms a
  LEFT JOIN public.districts dr ON dr.id = a.district_id::uuid
  LEFT JOIN LATERAL (
    SELECT sum(b.deduped_count)::int AS listing_count
    FROM public.market_benchmarks b
    WHERE b.snapshot_date = v_today AND b.source_type = 'asking' AND b.bedrooms_bucket = 'all'
      AND b.district_id = a.district_id
      AND (a.property_type = 'all' OR b.property_type = a.property_type)
  ) mk ON true
  LEFT JOIN LATERAL (
    SELECT count(DISTINCT o.id)::int AS our_count
    FROM public.records o
    JOIN public.records p ON (
      (jsonb_typeof(o.data->'project')='array' AND jsonb_exists(o.data->'project', p.id::text))
      OR o.data->>'project' = p.id::text)
    WHERE o.model_id = v_our_proj AND p.model_id = v_all_proj
      AND p.data->'location'->>'district' = a.district_id
  ) op ON true
  LEFT JOIN LATERAL (
    SELECT count(*)::int AS all_count
    FROM public.records p2
    WHERE p2.model_id = v_all_proj AND p2.data->'location'->>'district' = a.district_id
  ) ap ON true
  GROUP BY a.district_id, a.property_type, a.budget_bucket, mk.listing_count, op.our_count, ap.all_count;

  GET DIAGNOSTICS v_written = ROW_COUNT;
  RETURN v_written;
END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_refresh_market_benchmarks()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_market_model_id uuid := '8f06bc39-4bee-42e9-9fab-77023fb89ede';
  v_units_model_id  uuid := '7ca3014d-f658-418e-9c53-2d279c97f009';
  v_our_model_id    uuid := '6609286a-f95a-45db-94e6-48cfa915ccbd';
  v_today date := CURRENT_DATE;
  v_written int := 0;
BEGIN
  DELETE FROM public.market_benchmarks WHERE snapshot_date = v_today;

  CREATE TEMP TABLE _ml_norm ON COMMIT DROP AS
  SELECT
    (data->'location'->>'region')   AS region_id,
    (data->'location'->>'city')     AS city_id,
    (data->'location'->>'district') AS district_id,
    public.wassell_canon_property_type(data->>'property_type') AS canon_type,
    nullif(data->>'price','')::numeric        AS price,
    nullif(data->>'area','')::numeric         AS area,
    nullif(data->>'price_per_m2','')::numeric AS ppm2,
    nullif(data->>'bedrooms','')::numeric     AS bedrooms,
    md5(coalesce(data->'location'->>'district','') || '|' ||
        public.wassell_canon_property_type(data->>'property_type') || '|' ||
        coalesce(round(nullif(data->>'price','')::numeric)::text,'') || '|' ||
        coalesce(round(nullif(data->>'area','')::numeric)::text,'') || '|' ||
        coalesce(data->>'bedrooms','') || '|' ||
        coalesce(round(nullif(data->>'latitude','')::numeric, 4)::text,'') || '|' ||
        coalesce(round(nullif(data->>'longitude','')::numeric, 4)::text,'')
    ) AS fingerprint
  FROM public.records
  WHERE model_id = v_market_model_id
    AND coalesce(data->>'listing_type','sale') = 'sale'
    AND nullif(data->>'price','')::numeric > 0
    AND nullif(data->>'area','')::numeric > 0
    AND nullif(data->>'price_per_m2','')::numeric > 0
    AND (data->'location'->>'district') IS NOT NULL;

  ALTER TABLE _ml_norm ADD COLUMN bbucket text;
  UPDATE _ml_norm SET bbucket = CASE
    WHEN bedrooms IS NULL THEN 'all'
    WHEN bedrooms <= 2 THEN '1-2'
    WHEN bedrooms = 3 THEN '3'
    WHEN bedrooms = 4 THEN '4'
    ELSE '5+' END;

  CREATE TEMP TABLE _ml_dedup ON COMMIT DROP AS
  SELECT DISTINCT ON (fingerprint) * FROM _ml_norm ORDER BY fingerprint;

  CREATE TEMP TABLE _ml_raw_all ON COMMIT DROP AS
  SELECT district_id, canon_type, count(*) AS raw_count FROM _ml_norm GROUP BY 1,2;
  CREATE TEMP TABLE _ml_raw_bb ON COMMIT DROP AS
  SELECT district_id, canon_type, bbucket, count(*) AS raw_count FROM _ml_norm GROUP BY 1,2,3;

  INSERT INTO public.market_benchmarks (
    snapshot_date, region_id, city_id, district_id, district_name, district_name_en, city_name, property_type,
    bedrooms_bucket, area_bucket, source_type, raw_count, deduped_count, duplicate_ratio,
    median_price, p10_price, p25_price, p75_price, p90_price,
    median_price_per_sqm, p10_price_per_sqm, p25_price_per_sqm, p75_price_per_sqm, p90_price_per_sqm,
    min_price_per_sqm, max_price_per_sqm, median_area, confidence_grade, confidence_reason)
  SELECT
    v_today, max(d.region_id), max(d.city_id), d.district_id,
    max(coalesce(dr.name_ar, dr.display_name)), max(dr.name_en), max(dr.city_name_ar),
    d.canon_type, 'all', 'all', 'asking',
    r.raw_count, count(*)::int, round(1 - (count(*)::numeric / nullif(r.raw_count,0)), 4),
    percentile_cont(0.5) WITHIN GROUP (ORDER BY d.price),
    percentile_cont(0.1) WITHIN GROUP (ORDER BY d.price),
    percentile_cont(0.25) WITHIN GROUP (ORDER BY d.price),
    percentile_cont(0.75) WITHIN GROUP (ORDER BY d.price),
    percentile_cont(0.9) WITHIN GROUP (ORDER BY d.price),
    percentile_cont(0.5) WITHIN GROUP (ORDER BY d.ppm2),
    percentile_cont(0.1) WITHIN GROUP (ORDER BY d.ppm2),
    percentile_cont(0.25) WITHIN GROUP (ORDER BY d.ppm2),
    percentile_cont(0.75) WITHIN GROUP (ORDER BY d.ppm2),
    percentile_cont(0.9) WITHIN GROUP (ORDER BY d.ppm2),
    min(d.ppm2), max(d.ppm2),
    percentile_cont(0.5) WITHIN GROUP (ORDER BY d.area),
    public.wassell_benchmark_confidence(count(*)::int,
      round(1 - (count(*)::numeric / nullif(r.raw_count,0)), 4), 'asking', false),
    'asking-only; ' || count(*)::text || ' deduped of ' || r.raw_count::text || ' listings'
  FROM _ml_dedup d
  JOIN _ml_raw_all r ON r.district_id = d.district_id AND r.canon_type = d.canon_type
  LEFT JOIN public.districts dr ON dr.id = d.district_id::uuid
  GROUP BY d.district_id, d.canon_type, r.raw_count
  HAVING count(*) >= 3;

  GET DIAGNOSTICS v_written = ROW_COUNT;

  INSERT INTO public.market_benchmarks (
    snapshot_date, region_id, city_id, district_id, district_name, district_name_en, city_name, property_type,
    bedrooms_bucket, area_bucket, source_type, raw_count, deduped_count, duplicate_ratio,
    median_price, p10_price, p25_price, p75_price, p90_price,
    median_price_per_sqm, p10_price_per_sqm, p25_price_per_sqm, p75_price_per_sqm, p90_price_per_sqm,
    min_price_per_sqm, max_price_per_sqm, median_area, confidence_grade, confidence_reason)
  SELECT
    v_today, max(d.region_id), max(d.city_id), d.district_id,
    max(coalesce(dr.name_ar, dr.display_name)), max(dr.name_en), max(dr.city_name_ar),
    d.canon_type, d.bbucket, 'all', 'asking',
    r.raw_count, count(*)::int, round(1 - (count(*)::numeric / nullif(r.raw_count,0)), 4),
    percentile_cont(0.5) WITHIN GROUP (ORDER BY d.price),
    percentile_cont(0.1) WITHIN GROUP (ORDER BY d.price),
    percentile_cont(0.25) WITHIN GROUP (ORDER BY d.price),
    percentile_cont(0.75) WITHIN GROUP (ORDER BY d.price),
    percentile_cont(0.9) WITHIN GROUP (ORDER BY d.price),
    percentile_cont(0.5) WITHIN GROUP (ORDER BY d.ppm2),
    percentile_cont(0.1) WITHIN GROUP (ORDER BY d.ppm2),
    percentile_cont(0.25) WITHIN GROUP (ORDER BY d.ppm2),
    percentile_cont(0.75) WITHIN GROUP (ORDER BY d.ppm2),
    percentile_cont(0.9) WITHIN GROUP (ORDER BY d.ppm2),
    min(d.ppm2), max(d.ppm2),
    percentile_cont(0.5) WITHIN GROUP (ORDER BY d.area),
    public.wassell_benchmark_confidence(count(*)::int,
      round(1 - (count(*)::numeric / nullif(r.raw_count,0)), 4), 'asking', false),
    'asking-only; bedrooms ' || d.bbucket
  FROM _ml_dedup d
  JOIN _ml_raw_bb r ON r.district_id = d.district_id AND r.canon_type = d.canon_type AND r.bbucket = d.bbucket
  LEFT JOIN public.districts dr ON dr.id = d.district_id::uuid
  WHERE d.bbucket <> 'all'
  GROUP BY d.district_id, d.canon_type, d.bbucket, r.raw_count
  HAVING count(*) >= 5;

  INSERT INTO public.market_benchmarks (
    snapshot_date, region_id, city_id, district_id, district_name, district_name_en, city_name, property_type,
    bedrooms_bucket, area_bucket, source_type,
    raw_count, deduped_count, duplicate_ratio,
    median_price, p10_price, p25_price, p75_price, p90_price,
    median_price_per_sqm, p10_price_per_sqm, p25_price_per_sqm, p75_price_per_sqm, p90_price_per_sqm,
    min_price_per_sqm, max_price_per_sqm, median_area,
    confidence_grade, confidence_reason)
  SELECT
    v_today, max(u.region_id), max(u.city_id), u.district_id,
    max(coalesce(dr.name_ar, dr.display_name)), max(dr.name_en), max(dr.city_name_ar),
    u.canon_type, 'all', 'all', 'our_verified',
    count(*)::int, count(*)::int, 0,
    percentile_cont(0.5) WITHIN GROUP (ORDER BY u.price),
    percentile_cont(0.1) WITHIN GROUP (ORDER BY u.price),
    percentile_cont(0.25) WITHIN GROUP (ORDER BY u.price),
    percentile_cont(0.75) WITHIN GROUP (ORDER BY u.price),
    percentile_cont(0.9) WITHIN GROUP (ORDER BY u.price),
    percentile_cont(0.5) WITHIN GROUP (ORDER BY u.ppm2),
    percentile_cont(0.1) WITHIN GROUP (ORDER BY u.ppm2),
    percentile_cont(0.25) WITHIN GROUP (ORDER BY u.ppm2),
    percentile_cont(0.75) WITHIN GROUP (ORDER BY u.ppm2),
    percentile_cont(0.9) WITHIN GROUP (ORDER BY u.ppm2),
    min(u.ppm2), max(u.ppm2),
    percentile_cont(0.5) WITHIN GROUP (ORDER BY u.area),
    public.wassell_benchmark_confidence(count(*)::int, 0, 'our_verified', false),
    'verified Wassel units'
  FROM (
    SELECT
      (proj.data->'location'->>'region') AS region_id,
      (proj.data->'location'->>'city') AS city_id,
      (proj.data->'location'->>'district') AS district_id,
      public.wassell_canon_property_type(un.data->>'unit_type') AS canon_type,
      nullif(un.data->>'total_price','')::numeric AS price,
      nullif(un.data->>'unit_area','')::numeric AS area,
      CASE WHEN nullif(un.data->>'unit_area','')::numeric > 0
           THEN nullif(un.data->>'total_price','')::numeric / nullif(un.data->>'unit_area','')::numeric END AS ppm2
    FROM public.records un
    JOIN public.records proj
      ON proj.id = nullif(coalesce(un.data->>'project_id', un.data->'project_id'->>0),'')::uuid
    WHERE un.model_id = v_units_model_id
      AND EXISTS (
        SELECT 1 FROM public.records op
        WHERE op.model_id = v_our_model_id
          AND (
            (jsonb_typeof(op.data->'project') = 'array' AND jsonb_exists(op.data->'project', proj.id::text))
            OR op.data->>'project' = proj.id::text
          )
      )
      AND nullif(un.data->>'total_price','')::numeric > 0
      AND nullif(un.data->>'unit_area','')::numeric > 0
      AND (proj.data->'location'->>'district') IS NOT NULL
  ) u
  LEFT JOIN public.districts dr ON dr.id = u.district_id::uuid
  GROUP BY u.district_id, u.canon_type
  HAVING count(*) >= 1;

  UPDATE public.market_benchmarks a
  SET asking_transaction_gap_pct = round((a.median_price_per_sqm - t.median_price_per_sqm)
        / nullif(t.median_price_per_sqm,0) * 100, 1),
      transaction_count = t.deduped_count
  FROM public.market_benchmarks t
  WHERE a.snapshot_date = v_today AND a.source_type = 'asking'
    AND t.snapshot_date = v_today AND t.source_type = 'transaction'
    AND coalesce(a.district_id,'') = coalesce(t.district_id,'')
    AND a.property_type = t.property_type
    AND a.bedrooms_bucket = t.bedrooms_bucket;

  RETURN v_written;
END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_rep_owns_any_phone(p_rep uuid, p_phones text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_phones, ARRAY[]::text[])) AS ph
    JOIN LATERAL public.find_client_id_by_phone(ph) AS cid ON TRUE
    JOIN public.records c ON c.id = cid
    WHERE p_rep IS NOT NULL
      AND NULLIF(COALESCE(c.data->'client_owner'->>0, c.data->>'client_owner'), '') = p_rep::text
  );
$function$;
CREATE OR REPLACE FUNCTION public.wassell_role_rank(p_role text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_role
    WHEN 'owner'  THEN 3
    WHEN 'editor' THEN 2
    WHEN 'viewer' THEN 1
    ELSE 0
  END
$function$;
CREATE OR REPLACE FUNCTION public.wassell_role_satisfies(p_role text, p_kind text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_kind
    WHEN 'view'   THEN p_role IN ('viewer','editor','owner')
    WHEN 'edit'   THEN p_role IN ('editor','owner')
    WHEN 'delete' THEN p_role = 'owner'
    ELSE false
  END
$function$;
CREATE OR REPLACE FUNCTION public.wassell_search_geo_elements(p_q text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_type text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_limit integer DEFAULT 30, p_include_unapproved boolean DEFAULT false, p_country text DEFAULT NULL::text)
 RETURNS TABLE(external_id text, name_ar text, name_en text, display_name text, category text, type text, geom_kind text, city text, latitude double precision, longitude double precision, confidence_score numeric, is_verified boolean, is_approximate boolean, review_status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH q AS (SELECT lower(btrim(coalesce(p_q, ''))) AS term)
  SELECT
    e.external_id, e.name_ar, e.name_en, e.display_name,
    e.category, e.type, e.geom_kind, e.city,
    e.latitude, e.longitude, e.confidence_score, e.is_verified, e.is_approximate,
    e.review_status
  FROM public.geo_elements e, q
  WHERE e.external_id IS NOT NULL
    AND e.is_active
    AND (p_include_unapproved OR (e.is_searchable AND e.review_status = 'approved'))
    AND (p_category IS NULL OR e.category = p_category)
    AND (p_type     IS NULL OR e.type = p_type)
    AND (p_city     IS NULL OR e.city ILIKE p_city)
    AND (p_country  IS NULL OR e.country_code = p_country)
    AND (
      q.term = '' OR
      e.name_ar ILIKE '%' || q.term || '%' OR
      e.name_en ILIKE '%' || q.term || '%' OR
      e.display_name ILIKE '%' || q.term || '%' OR
      EXISTS (SELECT 1 FROM public.geo_element_aliases a
              WHERE a.element_id = e.id AND a.alias_norm ILIKE '%' || q.term || '%')
    )
  ORDER BY
    CASE
      WHEN q.term = '' THEN 2
      WHEN lower(coalesce(e.name_ar, '')) = q.term
        OR lower(coalesce(e.name_en, '')) = q.term
        OR lower(coalesce(e.display_name, '')) = q.term THEN 0
      WHEN lower(coalesce(e.name_ar, '')) LIKE q.term || '%'
        OR lower(coalesce(e.name_en, '')) LIKE q.term || '%'
        OR lower(coalesce(e.display_name, '')) LIKE q.term || '%' THEN 1
      ELSE 2
    END,
    e.is_verified DESC,
    e.confidence_score DESC NULLS LAST,
    length(coalesce(e.display_name, e.name_en, e.name_ar, '')),
    e.external_id
  LIMIT greatest(1, least(coalesce(p_limit, 30), 100))
$function$;
CREATE OR REPLACE FUNCTION public.wassell_user_has_action(auth_user_id uuid, the_model_id uuid, action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  prof profiles%ROWTYPE;
  model_perm jsonb;
BEGIN
  IF auth_user_id IS NULL THEN RETURN false; END IF;
  SELECT p.* INTO prof FROM profiles p
    JOIN users u ON u.profile_id = p.id
   WHERE u.auth_uid = auth_user_id AND u.is_active = true LIMIT 1;
  IF NOT FOUND THEN RETURN false; END IF;
  IF prof.is_admin THEN RETURN true; END IF;
  SELECT mp INTO model_perm FROM jsonb_array_elements(prof.model_permissions) mp
    WHERE (mp->>'model_id')::uuid = the_model_id LIMIT 1;
  IF model_perm IS NULL THEN RETURN false; END IF;
  RETURN (model_perm->'permissions') @> to_jsonb(action);
END $function$;
CREATE OR REPLACE FUNCTION public.wassell_view_scope_class(auth_user_id uuid, the_model_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  prof profiles%ROWTYPE;
  model_perm jsonb;
  rule jsonb;
BEGIN
  IF auth_user_id IS NULL THEN
    IF (NULLIF(current_setting('request.jwt.claims', true), ''))::jsonb->>'role' = 'service_role'
       OR current_setting('role', true) = 'service_role' THEN
      RETURN 'all';
    END IF;
    RETURN 'none';
  END IF;
  SELECT p.* INTO prof FROM profiles p
    JOIN users u ON u.profile_id = p.id
   WHERE u.auth_uid = auth_user_id AND u.is_active = true LIMIT 1;
  IF NOT FOUND THEN RETURN 'none'; END IF;
  IF prof.is_admin THEN RETURN 'all'; END IF;
  SELECT mp INTO model_perm FROM jsonb_array_elements(prof.model_permissions) mp
    WHERE (mp->>'model_id')::uuid = the_model_id LIMIT 1;
  IF model_perm IS NULL THEN RETURN 'none'; END IF;
  IF NOT ((model_perm->'permissions') @> to_jsonb('view'::text)) THEN RETURN 'none'; END IF;
  rule := model_perm -> 'view_scope';
  IF rule IS NULL THEN RETURN 'all'; END IF;
  IF rule->>'mode' = 'all' THEN RETURN 'all'; END IF;
  IF rule->>'mode' <> 'filtered' THEN RETURN 'all'; END IF;
  IF jsonb_array_length(COALESCE(rule->'conditions', '[]'::jsonb)) = 0 THEN RETURN 'all'; END IF;
  RETURN 'filtered';
END $function$;
CREATE OR REPLACE FUNCTION public.whatsapp_ai_enqueue(p_chat_wid text, p_chat_record_id uuid, p_phone text, p_device_id text, p_trigger_message text DEFAULT NULL::text, p_force boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ok boolean;
  v_id uuid;
BEGIN
  IF NOT p_force THEN
    SELECT should_reply INTO v_ok FROM public.whatsapp_ai_should_reply(p_chat_wid);
    IF NOT v_ok THEN RETURN NULL; END IF;
  END IF;

  -- Debounce: a live session for this chat will see the new messages anyway.
  SELECT id INTO v_id FROM public.claude_jobs
   WHERE kind = 'whatsapp_reply' AND status IN ('pending','running')
     AND payload->>'chat_wid' = p_chat_wid
   LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  INSERT INTO public.claude_jobs (kind, payload)
  VALUES ('whatsapp_reply', jsonb_build_object(
    'chat_wid',        p_chat_wid,
    'chat_record_id',  p_chat_record_id,
    'phone',           p_phone,
    'device_id',       p_device_id,
    'trigger_message', left(coalesce(p_trigger_message,''), 500),
    'forced',          p_force
  ))
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.whatsapp_ai_session_get(p_chat_wid text, p_max_tokens bigint DEFAULT 250000, p_max_age_hours integer DEFAULT 24)
 RETURNS TABLE(session_id text, turns integer, context_tokens bigint, last_used_at timestamp with time zone, reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s public.whatsapp_ai_sessions%ROWTYPE;
BEGIN
  SELECT * INTO s FROM public.whatsapp_ai_sessions WHERE chat_wid = p_chat_wid;
  IF NOT FOUND THEN
    RETURN QUERY SELECT NULL::text, 0, 0::bigint, NULL::timestamptz, 'no_session'; RETURN;
  END IF;
  IF s.context_tokens >= p_max_tokens THEN
    RETURN QUERY SELECT NULL::text, s.turns, s.context_tokens, s.last_used_at, 'context_full'; RETURN;
  END IF;
  IF s.last_used_at < now() - make_interval(hours => p_max_age_hours) THEN
    RETURN QUERY SELECT NULL::text, s.turns, s.context_tokens, s.last_used_at, 'stale'; RETURN;
  END IF;
  RETURN QUERY SELECT s.session_id, s.turns, s.context_tokens, s.last_used_at, 'resume';
END $function$;
CREATE OR REPLACE FUNCTION public.whatsapp_ai_session_put(p_chat_wid text, p_session_id text, p_tokens bigint, p_is_new boolean DEFAULT false, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.whatsapp_ai_sessions AS w
        (chat_wid, session_id, turns, context_tokens, last_error)
  VALUES (p_chat_wid, p_session_id, 1, GREATEST(p_tokens, 0), p_error)
  ON CONFLICT (chat_wid) DO UPDATE
     SET session_id     = EXCLUDED.session_id,
         last_used_at   = now(),
         -- A rotation restarts the counters; a resume accumulates.
         turns          = CASE WHEN p_is_new THEN 1 ELSE w.turns + 1 END,
         context_tokens = CASE WHEN p_is_new THEN GREATEST(p_tokens,0)
                               ELSE GREATEST(p_tokens, w.context_tokens) END,
         rotations      = w.rotations + CASE WHEN p_is_new THEN 1 ELSE 0 END,
         started_at     = CASE WHEN p_is_new THEN now() ELSE w.started_at END,
         last_error     = p_error;
END $function$;
CREATE OR REPLACE FUNCTION public.whatsapp_ai_set_chat_mode(p_chat_record_id uuid, p_enabled boolean, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_data jsonb;
BEGIN
  UPDATE public.records r
     SET data = r.data
              || jsonb_build_object('ai_managed', p_enabled)
              || CASE WHEN p_enabled
                      THEN jsonb_build_object('ai_managed_at', now()::text,
                                              'ai_managed_by', p_user_id)
                      ELSE jsonb_build_object('ai_stopped_at', now()::text) END
   WHERE r.id = p_chat_record_id
     AND r.model_id = (SELECT id FROM public.models WHERE name = 'chats')
  RETURNING r.data INTO v_data;
  IF v_data IS NULL THEN RAISE EXCEPTION 'chat record % not found', p_chat_record_id; END IF;
  RETURN jsonb_build_object('ai_managed', COALESCE((v_data->>'ai_managed')::boolean, false));
END $function$;
CREATE OR REPLACE FUNCTION public.whatsapp_ai_should_reply(p_chat_wid text, p_now timestamp with time zone DEFAULT now())
 RETURNS TABLE(should_reply boolean, reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s            public.whatsapp_ai_settings%ROWTYPE;
  v_managed    boolean;
  v_local      timestamptz;
  v_hour       int;
  v_dow        int;
  v_ai_count   int;
  v_last_human timestamptz;
BEGIN
  SELECT COALESCE((r.data->>'ai_managed')::boolean, false) INTO v_managed
  FROM public.records r
  WHERE r.model_id = (SELECT id FROM public.models WHERE name = 'chats')
    AND r.data->>'wid' = p_chat_wid
  LIMIT 1;
  v_managed := COALESCE(v_managed, false);

  -- The kill switch is absolute — it is checked BEFORE the takeover branch.
  SELECT * INTO s FROM public.whatsapp_ai_settings WHERE id LIMIT 1;
  IF NOT FOUND OR NOT s.is_enabled THEN
    RETURN QUERY SELECT false, CASE WHEN v_managed THEN 'disabled_globally_despite_takeover' ELSE 'disabled' END;
    RETURN;
  END IF;

  -- A human who has spoken since the agent last did outranks the handover.
  SELECT max(m.date) INTO v_last_human
  FROM public.chat_messages m
  WHERE m.chat_wid = p_chat_wid
    AND m.flow = 'out'
    AND NOT EXISTS (
      SELECT 1 FROM public.whatsapp_ai_replies r
      WHERE r.message_wid = m.id
         OR (r.chat_wid = m.chat_wid
             AND r.body IS NOT NULL AND m.body IS NOT NULL
             AND r.body = m.body
             AND abs(EXTRACT(EPOCH FROM (r.sent_at - m.date))) < 600)
    );
  IF v_last_human IS NOT NULL AND v_last_human > p_now - make_interval(hours => s.human_quiet_hours) THEN
    RETURN QUERY SELECT false, 'human_active'; RETURN;
  END IF;

  -- A ceiling applies to every chat. An agent with no cap on one conversation
  -- is exactly what a cap is for.
  SELECT count(*) INTO v_ai_count FROM public.whatsapp_ai_replies r WHERE r.chat_wid = p_chat_wid;
  IF v_ai_count >= s.max_replies_per_chat THEN
    RETURN QUERY SELECT false, 'reply_cap_reached'; RETURN;
  END IF;

  -- Only now does takeover buy anything: it skips the working-hours window.
  IF v_managed THEN
    RETURN QUERY SELECT true, 'chat_ai_managed'; RETURN;
  END IF;

  v_local := p_now AT TIME ZONE s.timezone;
  v_hour  := EXTRACT(HOUR  FROM v_local)::int;
  v_dow   := EXTRACT(ISODOW FROM v_local)::int;
  IF v_dow = ANY (s.work_days) AND v_hour >= s.work_start_hour AND v_hour < s.work_end_hour THEN
    RETURN QUERY SELECT false, 'working_hours'; RETURN;
  END IF;

  RETURN QUERY SELECT true, 'ok';
END $function$;
CREATE OR REPLACE FUNCTION public.whatsapp_inbound_health(p_stale_minutes integer DEFAULT 90)
 RETURNS TABLE(healthy boolean, last_inbound_at timestamp with time zone, minutes_since numeric, last_outbound_at timestamp with time zone, reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_in  timestamptz;
  v_out timestamptz;
  v_mins numeric;
BEGIN
  SELECT max(date) INTO v_in  FROM public.chat_messages WHERE flow = 'in';
  SELECT max(date) INTO v_out FROM public.chat_messages WHERE flow = 'out';
  v_mins := CASE WHEN v_in IS NULL THEN NULL
                 ELSE EXTRACT(EPOCH FROM (now() - v_in)) / 60 END;

  -- The telling shape is outbound MOVING while inbound is frozen: that is a
  -- half-dead socket, not a quiet day. A genuinely idle line has both stale.
  IF v_in IS NULL THEN
    RETURN QUERY SELECT false, v_in, v_mins, v_out, 'no inbound messages ever recorded';
  ELSIF v_mins > p_stale_minutes AND v_out IS NOT NULL AND v_out > v_in THEN
    RETURN QUERY SELECT false, v_in, v_mins, v_out,
      format('inbound silent %s min while outbound still flowing — likely half-dead session', round(v_mins));
  ELSIF v_mins > p_stale_minutes * 4 THEN
    RETURN QUERY SELECT false, v_in, v_mins, v_out,
      format('no inbound for %s min', round(v_mins));
  ELSE
    RETURN QUERY SELECT true, v_in, v_mins, v_out, 'ok';
  END IF;
END $function$;
CREATE OR REPLACE FUNCTION public.whatsapp_send_budget_remaining(p_device_id text)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH b AS (
    SELECT COALESCE(max_per_minute, 40) AS pm, COALESCE(max_per_hour, 600) AS ph
    FROM public.whatsapp_send_budget WHERE device_id = p_device_id
    UNION ALL SELECT 40, 600
    LIMIT 1
  ),
  used AS (
    SELECT
      count(*) FILTER (WHERE date > now() - interval '1 minute') AS m,
      count(*) FILTER (WHERE date > now() - interval '1 hour')   AS h
    FROM public.chat_messages
    WHERE device_id = p_device_id AND flow = 'out' AND date > now() - interval '1 hour'
  )
  SELECT GREATEST(0, LEAST(b.pm - used.m, b.ph - used.h))::int FROM b, used
$function$;
CREATE OR REPLACE FUNCTION public.workflow_action_emit_and_create(p_workflow_run_id uuid, p_workflow_id uuid, p_workflow_job_id uuid, p_action_id text, p_source_record_id uuid, p_target_model_id uuid, p_business_key text, p_new_record_id uuid, p_data jsonb, p_created_by uuid, p_depth integer, p_origin_run uuid, p_parent_job uuid)
 RETURNS TABLE(created_record_id uuid, is_new boolean, deduped_by text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_emission uuid;
  v_created  uuid;
BEGIN
  -- 1) FILLED-only dedup (fast path). An unfilled match is NOT a dedup hit.
  IF p_business_key IS NOT NULL THEN
    SELECT e.id, e.created_record_id INTO v_emission, v_created
      FROM public.workflow_action_emissions e
     WHERE e.workflow_id = p_workflow_id
       AND e.action_id   = p_action_id
       AND e.source_record_id IS NOT DISTINCT FROM p_source_record_id
       AND e.target_model_id  IS NOT DISTINCT FROM p_target_model_id
       AND e.business_key = p_business_key
       AND e.created_record_id IS NOT NULL
     LIMIT 1;
    IF FOUND THEN
      RETURN QUERY SELECT v_created, false, 'business_key'::text; RETURN;
    END IF;
  END IF;

  SELECT e.id, e.created_record_id INTO v_emission, v_created
    FROM public.workflow_action_emissions e
   WHERE e.workflow_run_id = p_workflow_run_id
     AND e.action_id       = p_action_id
     AND e.created_record_id IS NOT NULL
   LIMIT 1;
  IF FOUND THEN
    RETURN QUERY SELECT v_created, false, 'same_run'::text; RETURN;
  END IF;

  -- 2) Acquire the lock via INSERT (filled before commit; see step 4).
  v_emission := NULL;
  BEGIN
    INSERT INTO public.workflow_action_emissions
      (workflow_run_id, workflow_id, workflow_job_id, action_id,
       source_record_id, target_model_id, business_key)
    VALUES
      (p_workflow_run_id, p_workflow_id, p_workflow_job_id, p_action_id,
       p_source_record_id, p_target_model_id, p_business_key)
    RETURNING id INTO v_emission;
  EXCEPTION WHEN unique_violation THEN
    v_emission := NULL; v_created := NULL;
    IF p_business_key IS NOT NULL THEN
      SELECT e.id, e.created_record_id INTO v_emission, v_created
        FROM public.workflow_action_emissions e
       WHERE e.workflow_id = p_workflow_id
         AND e.action_id   = p_action_id
         AND e.source_record_id IS NOT DISTINCT FROM p_source_record_id
         AND e.target_model_id  IS NOT DISTINCT FROM p_target_model_id
         AND e.business_key = p_business_key
       LIMIT 1;
    END IF;
    IF v_emission IS NULL THEN
      SELECT e.id, e.created_record_id INTO v_emission, v_created
        FROM public.workflow_action_emissions e
       WHERE e.workflow_run_id = p_workflow_run_id
         AND e.action_id       = p_action_id
       LIMIT 1;
    END IF;

    IF v_emission IS NULL THEN
      RAISE EXCEPTION 'emit_and_create: unique_violation but no conflicting emission found (run=%, action=%)',
        p_workflow_run_id, p_action_id;
    END IF;

    IF v_created IS NOT NULL THEN
      RETURN QUERY SELECT v_created, false, 'filled_race'::text; RETURN;
    END IF;
    -- else: UNFILLED legacy orphan ⇒ reclaim v_emission and fill it in step 4.
  END;

  -- 3) Create the record (same tx as the emission lock above).
  PERFORM public.record_save_workflow(
    p_target_model_id, p_new_record_id, p_data, p_created_by, NULL,
    p_depth, p_origin_run, p_parent_job);

  -- 4) Fill the emission (newly inserted, or the reclaimed orphan).
  UPDATE public.workflow_action_emissions
     SET created_record_id = p_new_record_id,
         workflow_run_id   = p_workflow_run_id,
         workflow_job_id   = p_workflow_job_id
   WHERE id = v_emission;

  RETURN QUERY SELECT p_new_record_id, true, NULL::text;
END $function$;
CREATE OR REPLACE FUNCTION public.workflow_action_emit_fill(p_emission_id uuid, p_created_record_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  UPDATE public.workflow_action_emissions SET created_record_id = p_created_record_id WHERE id = p_emission_id;
$function$;
CREATE OR REPLACE FUNCTION public.workflow_action_emit_reserve(p_workflow_run_id uuid, p_workflow_id uuid, p_workflow_job_id uuid, p_action_id text, p_source_record_id uuid, p_target_model_id uuid, p_business_key text)
 RETURNS TABLE(emission_id uuid, created_record_id uuid, is_new boolean, deduped_by text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id      uuid;
  v_created uuid;
BEGIN
  IF p_business_key IS NOT NULL THEN
    SELECT e.id, e.created_record_id INTO v_id, v_created
      FROM public.workflow_action_emissions e
     WHERE e.workflow_id = p_workflow_id
       AND e.action_id   = p_action_id
       AND e.source_record_id IS NOT DISTINCT FROM p_source_record_id
       AND e.target_model_id  IS NOT DISTINCT FROM p_target_model_id
       AND e.business_key = p_business_key
     LIMIT 1;
    IF FOUND THEN
      RETURN QUERY SELECT v_id, v_created, false, 'business_key'::text; RETURN;
    END IF;
  END IF;

  SELECT e.id, e.created_record_id INTO v_id, v_created
    FROM public.workflow_action_emissions e
   WHERE e.workflow_run_id = p_workflow_run_id AND e.action_id = p_action_id;
  IF FOUND THEN
    RETURN QUERY SELECT v_id, v_created, false, 'same_run'::text; RETURN;
  END IF;

  BEGIN
    INSERT INTO public.workflow_action_emissions
      (workflow_run_id, workflow_id, workflow_job_id, action_id,
       source_record_id, target_model_id, business_key)
    VALUES
      (p_workflow_run_id, p_workflow_id, p_workflow_job_id, p_action_id,
       p_source_record_id, p_target_model_id, p_business_key)
    RETURNING id INTO v_id;
    RETURN QUERY SELECT v_id, NULL::uuid, true, NULL::text; RETURN;
  EXCEPTION WHEN unique_violation THEN
    IF p_business_key IS NOT NULL THEN
      SELECT e.id, e.created_record_id INTO v_id, v_created
        FROM public.workflow_action_emissions e
       WHERE e.workflow_id = p_workflow_id
         AND e.action_id   = p_action_id
         AND e.source_record_id IS NOT DISTINCT FROM p_source_record_id
         AND e.target_model_id  IS NOT DISTINCT FROM p_target_model_id
         AND e.business_key = p_business_key
       LIMIT 1;
      IF FOUND THEN
        RETURN QUERY SELECT v_id, v_created, false, 'business_key_race'::text; RETURN;
      END IF;
    END IF;
    SELECT e.id, e.created_record_id INTO v_id, v_created
      FROM public.workflow_action_emissions e
     WHERE e.workflow_run_id = p_workflow_run_id AND e.action_id = p_action_id;
    RETURN QUERY SELECT v_id, v_created, false, 'same_run_race'::text; RETURN;
  END;
END $function$;
CREATE OR REPLACE FUNCTION public.workflow_job_claim_next(p_worker_id text)
 RETURNS TABLE(job_id uuid, model_id uuid, record_id uuid, trigger_event text, previous_data jsonb, new_data jsonb, changed_fields text[], actor_user_id uuid, depth integer, origin_run_id uuid, attempts integer)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  UPDATE public.workflow_jobs
     SET status='processing', locked_by=p_worker_id, locked_at=now(),
         updated_at=now(), attempts=workflow_jobs.attempts+1
   WHERE id = (
     SELECT id FROM public.workflow_jobs
      WHERE status='pending' AND available_at <= now()
      ORDER BY available_at FOR UPDATE SKIP LOCKED LIMIT 1
   )
   RETURNING id, model_id, record_id, trigger_event, previous_data, new_data,
             changed_fields, actor_user_id, depth, origin_run_id, attempts;
$function$;
CREATE OR REPLACE FUNCTION public.workflow_job_complete(p_job_id uuid)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH updated AS (
    UPDATE public.workflow_jobs
       SET status='completed', completed_at=now(), updated_at=now(), error=NULL
     WHERE id=p_job_id AND status='processing'
    RETURNING 1
  ) SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.workflow_job_fail(p_job_id uuid, p_error text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_attempts int; v_max int;
BEGIN
  SELECT attempts, max_attempts INTO v_attempts, v_max
    FROM public.workflow_jobs WHERE id=p_job_id AND status='processing';
  IF NOT FOUND THEN RETURN false; END IF;
  IF v_attempts >= v_max THEN
    UPDATE public.workflow_jobs
       SET status='dead', error=p_error, completed_at=now(), updated_at=now(),
           locked_at=NULL, locked_by=NULL
     WHERE id=p_job_id;
  ELSE
    UPDATE public.workflow_jobs
       SET status='pending', error=p_error, updated_at=now(),
           locked_at=NULL, locked_by=NULL,
           available_at=now() + make_interval(secs => 30 * v_attempts)
     WHERE id=p_job_id;
  END IF;
  RETURN true;
END $function$;
CREATE OR REPLACE FUNCTION public.workflow_jobs_watchdog()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_count int := 0;
BEGIN
  WITH stale AS (
    SELECT id, attempts, max_attempts FROM public.workflow_jobs
     WHERE status='processing' AND locked_at < now() - interval '10 minutes'
  ), bumped AS (
    UPDATE public.workflow_jobs j
       SET status = CASE WHEN s.attempts >= s.max_attempts THEN 'dead' ELSE 'pending' END,
           locked_at=NULL, locked_by=NULL, available_at=now(),
           error=COALESCE(j.error,'watchdog: worker lease expired (>10m processing)'),
           updated_at=now()
      FROM stale s WHERE j.id=s.id RETURNING 1
  ) SELECT COUNT(*) INTO v_count FROM bumped;
  RETURN v_count;
END $function$;

